void FastVectorMath::_bind_methods() {
	ClassDB::bind_static_method(
			"FastVectorMath",
			D_METHOD("dot_product", "a", "b"),
			&FastVectorMath::dot_product);

	ClassDB::bind_static_method(
			"FastVectorMath",
			D_METHOD("cross_product", "a", "b"),
			&FastVectorMath::cross_product);

	ClassDB::bind_static_method(
			"FastVectorMath",
			D_METHOD("compute_centroid_and_bounds", "points"),
			&FastVectorMath::compute_centroid_and_bounds);

	ClassDB::bind_static_method(
			"FastVectorMath",
			D_METHOD("ray_sphere_intersection", "origin", "dir", "sphere_center", "radius"),
			&FastVectorMath::ray_sphere_intersection);
}

real_t FastVectorMath::dot_product(Vector3 a, Vector3 b) {
	return a.dot(b);
}

Vector3 FastVectorMath::cross_product(Vector3 a, Vector3 b) {
	return a.cross(b);
}

Array FastVectorMath::compute_centroid_and_bounds(const PackedVector3Array &points) {
	Array result;
	result.push_back(Vector3(0.0, 0.0, 0.0)); // centroid
	result.push_back(Vector3(0.0, 0.0, 0.0)); // min_bounds
	result.push_back(Vector3(0.0, 0.0, 0.0)); // max_bounds

	if (points.is_empty()) {
		return result;
	}

	Vector3 min_bounds(std::numeric_limits<real_t>::infinity(),
			std::numeric_limits<real_t>::infinity(),
			std::numeric_limits<real_t>::infinity());
	Vector3 max_bounds(-std::numeric_limits<real_t>::infinity(),
			-std::numeric_limits<real_t>::infinity(),
			-std::numeric_limits<real_t>::infinity());
	Vector3 centroid(0.0, 0.0, 0.0);

	for (const Vector3 &p : points) {
		centroid += p;

		min_bounds.x = std::min(min_bounds.x, p.x);
		min_bounds.y = std::min(min_bounds.y, p.y);
		min_bounds.z = std::min(min_bounds.z, p.z);

		max_bounds.x = std::max(max_bounds.x, p.x);
		max_bounds.y = std::max(max_bounds.y, p.y);
		max_bounds.z = std::max(max_bounds.z, p.z);
	}

	centroid /= static_cast<real_t>(points.size());

	result[0] = centroid;
	result[1] = min_bounds;
	result[2] = max_bounds;

	return result;
}

real_t FastVectorMath::ray_sphere_intersection(Vector3 origin, Vector3 dir, Vector3 sphere_center, real_t radius) {
	// Ray: P = origin + dir * t, t >= 0
	// Sphere: (P - sphere_center) . (P - sphere_center) = radius^2
	//
	// Normalizing the direction is required for the geometric formula to work.
	real_t length_sq = dir.length_squared();
	if (length_sq == 0.0) {
		return -1.0;
	}

	Vector3 L = sphere_center - origin;
	// normalize dir
	rigid_t inv_len = 1.0 / Math::sqrt(length_sq);
	Vector3 n_dir = dir * inv_len;

	real_t tca = L.dot(n_dir);
	real_t d2 = L.dot(L) - tca * tca;
	real_t radius2 = radius * radius;

	if (d2 > radius2) {
		return -1.0;
	}

	real_t thc = Math::sqrt(radius2 - d2);
	real_t t0 = tca - thc;
	real_t t1 = tca + thc;

	if (t0 >= 0.0) {
		return t0;
	}
	// Use the further intersection point if the ray starts inside the sphere.
	if (t1 >= 0.0) {
		return t1;
	}

	return -1.0;
}

